{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2176-11-19 01:00:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be taking care of you tonight. Can you tell me what brought you to the hospital?"
    },
    {
      "turn_number": 2,
      "time": "2176-11-19 01:02:00",
      "speaker": "Patient",
      "text": "Hi, I came in because my INR was really high—like 19. I fell a few days ago and broke my ankle, but they didn’t check my blood then. I’ve been feeling off since."
    },
    {
      "turn_number": 3,
      "time": "2176-11-19 01:04:00",
      "speaker": "Doctor",
      "text": "Yes, your INR was dangerously high. That means your blood is too thin. Did you change your warfarin dose recently?"
    },
    {
      "turn_number": 4,
      "time": "2176-11-19 01:05:30",
      "speaker": "Patient",
      "text": "No, I’ve been taking 3 mg daily like always. The only new thing is Percocet for my ankle pain."
    },
    {
      "turn_number": 5,
      "time": "2176-11-19 01:07:00",
      "speaker": "Doctor",
      "text": "We gave you vitamin K and fluids to reverse the effect. We’re also watching for any signs of bleeding."
    },
    {
      "turn_number": 6,
      "time": "2176-11-19 01:08:30",
      "speaker": "Patient",
      "text": "I did vomit dark red blood that morning. And I’ve had blood when I blow my nose."
    },
    {
      "turn_number": 7,
      "time": "2176-11-19 01:10:00",
      "speaker": "Doctor",
      "text": "That’s important. We saw you were guaiac positive, meaning there’s blood in your stool. But your hemoglobin is stable, so no active major bleed now."
    },
    {
      "turn_number": 8,
      "time": "2176-11-19 01:12:00",
      "speaker": "Patient",
      "text": "Is that from the warfarin? Should I stop it?"
    },
    {
      "turn_number": 9,
      "time": "2176-11-19 01:13:30",
      "speaker": "Doctor",
      "text": "We paused it for now. Hematology thinks you don’t need a heparin bridge since your transplant failed. We’ll restart carefully later."
    },
    {
      "turn_number": 10,
      "time": "2176-11-19 01:15:00",
      "speaker": "Patient",
      "text": "I’ve also been confused. I forgot I needed dialysis one day. Is that normal?"
    },
    {
      "turn_number": 11,
      "time": "2176-11-19 01:17:00",
      "speaker": "Doctor",
      "text": "We’re concerned about that. Your labs show high potassium and kidney failure, which can affect brain function. Nephrology is adjusting your dialysis."
    },
    {
      "turn_number": 12,
      "time": "2176-11-19 01:19:00",
      "speaker": "Patient",
      "text": "I’ve been doing peritoneal dialysis at home. It’s been harder since the fall."
    },
    {
      "turn_number": 13,
      "time": "2176-11-19 01:21:00",
      "speaker": "Doctor",
      "text": "We did a dialysis treatment today. Your potassium was 6.9, which is dangerous. We gave insulin and sugar to bring it down."
    },
    {
      "turn_number": 14,
      "time": "2176-11-19 01:23:00",
      "speaker": "Patient",
      "text": "Oh, that makes sense. I felt weak and lightheaded."
    },
    {
      "turn_number": 15,
      "time": "2176-11-19 01:24:30",
      "speaker": "Doctor",
      "text": "Yes, that’s from the high potassium and low blood pressure. We’re giving fluids and watching closely."
    },
    {
      "turn_number": 16,
      "time": "2176-11-20 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your INR is down to 1.2 now—much safer. But we’re still not sure why it spiked so high."
    },
    {
      "turn_number": 17,
      "time": "2176-11-20 08:02:00",
      "speaker": "Patient",
      "text": "Could it be the new warfarin pills? I got a refill last week."
    },
    {
      "turn_number": 18,
      "time": "2176-11-20 08:04:00",
      "speaker": "Doctor",
      "text": "Possibly. We suggest not using that bottle and getting a new prescription. Pill count showed you actually underdosed, so it’s confusing."
    },
    {
      "turn_number": 19,
      "time": "2176-11-20 08:06:00",
      "speaker": "Patient",
      "text": "I use a weekly pillbox. Maybe I mixed up old and new bottles?"
    },
    {
      "turn_number": 20,
      "time": "2176-11-20 08:08:00",
      "speaker": "Doctor",
      "text": "That could happen. We’ll restart warfarin at a lower dose and monitor closely. Your GI team also recommends staying on high-dose pantoprazole."
    },
    {
      "turn_number": 21,
      "time": "2176-11-20 08:10:00",
      "speaker": "Patient",
      "text": "I’ve had heartburn since I started dialysis. Is that related?"
    },
    {
      "turn_number": 22,
      "time": "2176-11-20 08:12:00",
      "speaker": "Doctor",
      "text": "Yes, it’s common. We’ve increased your pantoprazole to twice daily to protect your stomach."
    },
    {
      "turn_number": 23,
      "time": "2176-11-20 12:30:00",
      "speaker": "Patient",
      "text": "Last night I had sharp chest pain and shoulder blade pain. I got really anxious."
    },
    {
      "turn_number": 24,
      "time": "2176-11-20 12:32:00",
      "speaker": "Doctor",
      "text": "We checked a chest X-ray and ECG. No heart or lung issues. It was likely from your full dialysis bag pressing on your diaphragm."
    },
    {
      "turn_number": 25,
      "time": "2176-11-20 12:34:00",
      "speaker": "Patient",
      "text": "That makes sense. I felt better after draining it."
    },
    {
      "turn_number": 26,
      "time": "2176-11-20 12:36:00",
      "speaker": "Doctor",
      "text": "Exactly. Anxiety can make it feel worse. We’ll keep your dialysis schedule consistent to avoid that."
    },
    {
      "turn_number": 27,
      "time": "2176-11-20 15:00:00",
      "speaker": "Doctor",
      "text": "We reviewed your chest CT. No signs of bleeding or infection. Your lungs look stable."
    },
    {
      "turn_number": 28,
      "time": "2176-11-20 15:02:00",
      "speaker": "Patient",
      "text": "Good. I was worried because of my past lung bleeds."
    },
    {
      "turn_number": 29,
      "time": "2176-11-20 15:04:00",
      "speaker": "Doctor",
      "text": "Understandable. But this scan is reassuring. Your main issues are the high INR, GI bleed, and kidney function."
    },
    {
      "turn_number": 30,
      "time": "2176-11-20 18:00:00",
      "speaker": "Patient",
      "text": "I still feel a little shaky in my hands. Is that from the meds?"
    },
    {
      "turn_number": 31,
      "time": "2176-11-20 18:02:00",
      "speaker": "Doctor",
      "text": "Possibly. Ziprasidone can cause tremors. Since you’re on long-term steroids, it was started for mood stability. We’ll consider adjusting it later."
    },
    {
      "turn_number": 32,
      "time": "2176-11-20 18:04:00",
      "speaker": "Patient",
      "text": "I’d like that. I’m not manic, just anxious."
    },
    {
      "turn_number": 33,
      "time": "2176-11-20 18:06:00",
      "speaker": "Doctor",
      "text": "We’ll discuss with your psychiatrist. For now, we’re keeping your other depression meds the same."
    },
    {
      "turn_number": 34,
      "time": "2176-11-21 07:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Your INR is stable, potassium is normal, and you’re not bleeding. We’re planning to discharge you today."
    },
    {
      "turn_number": 35,
      "time": "2176-11-21 07:02:00",
      "speaker": "Patient",
      "text": "That’s great. What about my warfarin?"
    },
    {
      "turn_number": 36,
      "time": "2176-11-21 07:04:00",
      "speaker": "Doctor",
      "text": "You’ll take six 1 mg tablets for the next two nights—so double dose—to catch up. Then go back to three. Follow up with your clinic in a few days."
    },
    {
      "turn_number": 37,
      "time": "2176-11-21 07:06:00",
      "speaker": "Patient",
      "text": "And my blood pressure meds? I was on metoprolol and lisinopril."
    },
    {
      "turn_number": 38,
      "time": "2176-11-21 07:08:00",
      "speaker": "Doctor",
      "text": "Take half your metoprolol this weekend. Resume full dose after talking to your doctor. Lisinopril is back on."
    },
    {
      "turn_number": 39,
      "time": "2176-11-21 07:10:00",
      "speaker": "Patient",
      "text": "Should I get an endoscopy for the stomach bleed?"
    },
    {
      "turn_number": 40,
      "time": "2176-11-21 07:12:00",
      "speaker": "Doctor",
      "text": "It’s not urgent now. Discuss it with your GI doctor as an outpatient."
    },
    {
      "turn_number": 41,
      "time": "2176-11-21 07:14:00",
      "speaker": "Patient",
      "text": "And my constipation? I’ve been using lactulose."
    },
    {
      "turn_number": 42,
      "time": "2176-11-21 07:16:00",
      "speaker": "Doctor",
      "text": "We’re adding senna and docusate to help. Keep using lactulose as needed."
    },
    {
      "turn_number": 43,
      "time": "2176-11-21 07:18:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better already."
    },
    {
      "turn_number": 44,
      "time": "2176-11-21 07:20:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. Just keep up with dialysis, take your meds as directed, and follow up closely."
    },
    {
      "turn_number": 45,
      "time": "2176-11-21 07:22:00",
      "speaker": "Patient",
      "text": "I will. Thanks for explaining everything."
    },
    {
      "turn_number": 46,
      "time": "2176-11-21 07:24:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll have your discharge papers ready soon. You can go home today."
    }
  ],
  "summary": {
    "admission_start": "2176-11-19 00:32:00",
    "admission_end": "2176-11-21 16:41:00",
    "summary_paragraph": "A female patient with systemic lupus erythematosus, antiphospholipid syndrome, end-stage renal disease on peritoneal dialysis, and a history of renal transplant failure was admitted with a supratherapeutic INR of 19.1 following an ankle fracture and episodes of hematemesis and epistaxis. She was treated with IV vitamin K, FFP, and pantoprazole, with successful reversal of anticoagulation. Her INR stabilized, and no active bleeding was observed. Hyperkalemia was managed with insulin and dextrose, and dialysis was adjusted. Confusion was attributed to uremia and metabolic imbalances. Chest pain was linked to peritoneal dialysis dwell volume. She was discharged home with a revised warfarin regimen, continued PPI therapy, and follow-up plans for INR monitoring and GI evaluation.",
    "problems": [
      "Hemorrhage of gastrointestinal tract, unspecified",
      "End stage renal disease",
      "Abnormal coagulation profile",
      "Epistaxis",
      "Anticoagulants causing adverse effects in therapeutic use",
      "Renal dialysis status",
      "Systemic lupus erythematosus",
      "Constipation, unspecified",
      "Esophageal reflux",
      "Hyperpotassemia",
      "Hypotension, unspecified"
    ]
  }
}
